# Parse the graph and find parents of a87ff679a2
edges_text = context.split("The graph has the following edges:\n")[1].split("\n\nOperation:")[0]

parents = set()
for line in edges_text.strip().split('\n'):
    if ' -> ' in line:
        source, dest = line.split(' -> ')
        if dest == 'a87ff679a2':
            parents.add(source)

print("Parents found:", sorted(parents))
